"""AWS Lambda compatibility wrapper for the locally tested v4.4 opportunity pipeline.

Handler: handler.lambda_handler
Environment keys preserved from the original handler.py:
  OPENAI_API_KEY, MONGODB_URI, OPPORTUNITY_EMAIL_FROM, OPPORTUNITY_EMAIL_TO,
  OPENAI_MODEL, LOOKBACK_DAYS, MINIMUM_MATCH_SCORE,
  INCLUDE_POSSIBLE_MATCHES, INCLUDE_INVESTIGATION_LEADS,
  MAX_EMAIL_OPPORTUNITIES_PER_COMPANY, ENABLE_OPENAI_WEB_SEARCH.
Optional: OPPORTUNITY_DEBUG_S3_BUCKET for diagnostic artifacts.

No automatically certified 'pursue' tiers: document coverage is incomplete.
"""


import json
import html
import re
import hashlib
import logging
import os
import tempfile
from datetime import datetime, timezone
from pathlib import Path
from types import SimpleNamespace

LOG = logging.getLogger(__name__)
LOG.setLevel(logging.INFO)
VERSION = 'local-pilot-4.4-lambda-digest-v1'
COMPANIES = ('boring', 'farawatt', 'vivesound')


def _email_body(leads):
    lines = ['CONTRACT PURSUIT DIGEST', 'Investigate only: findings are not certified bid eligibility.',
             'Check issuer documents, addenda and insurance before bidding.', '']
    for company in COMPANIES:
        matches = [v for v in leads if v['company'] == company]
        if not matches:
            continue
        lines += ['=' * 50, company.upper(), '=' * 50]
        for v in matches:
            lines += ['', v['title'], f"Buyer: {v['organization']}",
                      f"Status: {v['tier'].upper()} (not bid-ready)",
                      f"Issuer verified: {v['source_quality']}", f"Source: {v['url']}",
                      f"Next action: {v['next_action']}"]
            for category in ('deadline', 'insurance', 'qualifications', 'submission', 'scope'):
                items = v['requirements_by_type'].get(category, [])
                for item in items[:4]:
                    lines.append(f"{category.upper()}: {item['finding']} [{item['document_key']} line {item['line']}]")
            if v['unknowns']:
                lines += ['REMAINING CHECKS: ' + '; '.join(v['unknowns'][:5])]
    return '\n'.join(lines)



def _project_key(lead):
    """Avoid duplicate unverified notices even when aggregators disagree on buyer."""
    title = (lead.get('title') or '').lower().replace('arch flash', 'arc flash')
    words = re.findall(r'[a-z0-9]+', title)
    stop = {'rfp','rfq','bid','request','for','proposal','proposals','services','service','of','the',
            'at','and','2026','study','design','evaluation','website'}
    meaningful = sorted(set(w for w in words if w not in stop))
    # Don't merge generic website redesigns across buyers.
    if len(meaningful) < 3:
        buyer = re.sub(r'[^a-z0-9]+','', (lead.get('buyer') or lead.get('organization') or '').lower())
        return 'buyer:' + buyer + ':' + '-'.join(meaningful)
    return 'project:' + '-'.join(meaningful)


def _expiration_check(lead, day):
    """Only suppress explicit, parseable proposal-close dates, never inferred dates."""
    from datetime import date
    for name in ('deadline','due_date','submission_deadline','closing_date','close_date'):
        val = lead.get(name)
        if not isinstance(val, str) or not val.strip():
            continue
        m = re.search(r'\b(20\d{2})-(\d{2})-(\d{2})\b', val)
        if not m:
            continue
        try:
            deadline = date(*map(int,m.groups()))
            if deadline < date.fromisoformat(day):
                return True, deadline.isoformat(), name
            return False, deadline.isoformat(), name
        except ValueError:
            pass
    return False, None, None


def _email_html(leads, day):
    """SES-compatible HTML, safe escaped content, email-client friendly tables."""
    esc = lambda x: html.escape(str(x or ''), quote=True)
    verified = [x for x in leads if x['tier'] != 'unverified']
    unverified = [x for x in leads if x['tier'] == 'unverified']
    out = ['<!doctype html><html><head><meta charset="utf-8"></head>',
           '<body style="margin:0;background:#f3f5f8;color:#192536;font-family:Arial,Helvetica,sans-serif">',
           '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tr><td align="center" style="padding:24px 12px">',
           '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="max-width:700px;background:#ffffff;border:1px solid #e4e9ef">',
           '<tr><td style="padding:27px 30px 18px;background:#172b45;color:#ffffff"><div style="font-size:12px;letter-spacing:1.7px;text-transform:uppercase;color:#c9d9eb">Opportunity intelligence</div>',
           '<h1 style="font-size:25px;line-height:1.25;margin:10px 0 6px">Procurement opportunities</h1>',
           f'<div style="font-size:14px;color:#d8e5f3">{esc(day)} · {len(verified)} reviewed · {len(unverified)} unverified leads</div></td></tr>',
           '<tr><td style="padding:18px 30px;font-size:13px;line-height:1.55;color:#566579;border-bottom:1px solid #e8edf3">',
           'Unverified does <b>not</b> mean unsuitable. Verify buyer, closing date, eligibility and official bid documents before investing in a proposal.</td></tr>']
    for section, matches, label, accent in [('Reviewed on issuer source',verified,'REVIEWED','#176a5b'),
                                            ('Unverified leads worth checking',unverified,'UNVERIFIED','#a26522')]:
        if not matches: continue
        out.append(f'<tr><td style="padding:23px 30px 8px"><h2 style="font-size:16px;margin:0;color:#243449">{esc(section)} <span style="color:#75849a">({len(matches)})</span></h2></td></tr>')
        for x in matches:
            url=str(x.get('url') or '')
            safe_url=esc(url) if url.startswith(('https://','http://')) else ''
            link=(f'<a href="{safe_url}" style="color:#1266a8;text-decoration:underline">Open listing →</a>' if safe_url else '')
            details = (x.get('next_action') or 'Find the original buyer notice and confirm deadline and eligibility.')
            out.extend(['<tr><td style="padding:10px 30px 13px">',
                        '<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border:1px solid #e4e9ef;border-radius:7px"><tr><td style="padding:18px">',
                        f'<div style="color:{accent};font-size:11px;font-weight:bold;letter-spacing:1px">{label} · {esc(x.get("company", "").upper())}</div>',
                        f'<div style="font-size:17px;font-weight:bold;line-height:1.35;margin:7px 0">{esc(x.get("title"))}</div>',
                        f'<div style="font-size:13px;color:#566579;margin-bottom:9px">{esc(x.get("organization"))} · Deadline: {esc(x.get("deadline") or "Unconfirmed")}</div>',
                        f'<div style="font-size:13px;line-height:1.5;margin-bottom:10px"><b>Next step:</b> {esc(details)}</div>'])
            if x.get('verification_reason'):
                out.append(f'<div style="font-size:12px;color:#8b5a2b;margin-bottom:10px"><b>Verification:</b> {esc(x["verification_reason"])}</div>')
            if x.get('requirements_by_type'):
                for cat in ('insurance','qualifications','submission','scope'):
                    vals = [y for y in x['requirements_by_type'].get(cat,[]) if y.get('finding') and y.get('extraction_method')=='ai'][:2]
                    for y in vals:
                        out.append(f'<div style="font-size:12px;line-height:1.5;margin-bottom:4px"><b>{esc(cat.title())}:</b> {esc(y["finding"])}</div>')
            out.extend([f'<div style="font-size:13px;margin-top:12px">{link}</div>', '</td></tr></table></td></tr>'])
    out.extend(['<tr><td style="padding:20px 30px 26px;border-top:1px solid #e8edf3;font-size:12px;line-height:1.5;color:#65758b">',
                'These leads are research suggestions, not verified open bid invitations. Dates and buyer identities on third-party sites may be incorrect.',
                '</td></tr></table></td></tr></table></body></html>'])
    return ''.join(out)


def _email_text(leads, day):
    lines=[f'PROCUREMENT OPPORTUNITIES — {day}', 'UNVERIFIED means not confirmed, not necessarily unsuitable.', '']
    for tier,label in [('investigate','REVIEWED ON ISSUER SOURCE'),('unverified','UNVERIFIED — CHECK FIRST')]:
        group=[x for x in leads if x['tier']==tier]
        if not group: continue
        lines += [label, '-'*len(label)]
        for x in group:
            lines.extend([f'[{x["company"].upper()}] {x["title"]}',
                          f'Buyer: {x.get("organization") or "Unknown"}',
                          f'Deadline: {x.get("deadline") or "Unconfirmed"}',
                          f'Next: {x.get("next_action") or "Verify official notice and closing date"}',
                          f'URL: {x.get("url") or "Unknown"}', ''])
    return '\n'.join(lines)

def lambda_handler(event, context):
    """Discover -> issuer-resolve -> cite-reviewed RFP -> Mongo dedupe -> optional SES.

    Test without outbound email: {"dry_run": true, "companies": ["boring"]}.
    For a free deployment smoke check: {"dry_run": true, "discovery": false, "ai": false,
                                       "input_leads": [{...}]}; no paid API calls.
    Lambda result preserves legacy top-level count/status keys.
    """
    import boto3
    from pymongo import MongoClient
    import opportunity_pilot as pilot
    import rfp_review

    event = event if isinstance(event, dict) else {}
    now = datetime.now(timezone.utc)
    companies = event.get('companies', list(COMPANIES))
    if not isinstance(companies, list) or not companies or any(c not in COMPANIES for c in companies):
        raise ValueError('companies must be a nonempty list of boring, farawatt, vivesound')
    dry_run = event.get('dry_run') is True
    ai = event.get('ai', True) is True
    discovery_enabled = event.get('discovery', True) is True
    if discovery_enabled and not os.getenv('OPENAI_API_KEY'):
        raise ValueError('Set OPENAI_API_KEY')
    if ai and not os.getenv('OPENAI_API_KEY'):
        raise ValueError('Set OPENAI_API_KEY or select ai=false')
    mongo_uri = os.getenv('MONGODB_URI', '')
    if not mongo_uri:
        raise ValueError('Set MONGODB_URI (legacy environment key)')
    sender = os.getenv('OPPORTUNITY_EMAIL_FROM', '')
    to = os.getenv('OPPORTUNITY_EMAIL_TO', '')
    if not dry_run and (not sender or not to):
        raise ValueError('Set OPPORTUNITY_EMAIL_FROM and OPPORTUNITY_EMAIL_TO or dry_run=true')

    # Fixed runtime limits. Legacy MAX_* / NOTICE_TIMEOUT_SECONDS Lambda
    # environment variables are intentionally ignored to avoid incompatibility
    # with settings left over from the previous handler.
    per_company = 5
    max_search_calls = 2
    max_review_leads = 2
    max_ai_calls = 4
    timeout = 12
    max_docs = 6
    review_model = os.getenv('OPENAI_MODEL', 'gpt-4.1-mini')
    search_model = os.getenv('WEB_RESEARCH_MODEL', 'gpt-4.1-mini')
    day = now.date().isoformat()
    debug_bucket = os.getenv('OPPORTUNITY_DEBUG_S3_BUCKET', '').strip()
    # Never log API keys, Mongo URI, or full OpenAI request payloads to CloudWatch.
    result = {'version': VERSION, 'mode': 'shadow_research' if dry_run else 'scheduled_research',
              'emailed': 0, 'found': 0, 'reviewed': 0, 'cached': 0,
              'classification_errors': 0, 'plan_failures': 0, 'search_failures': 0,
              'already_notified': 0, 'details_checked': 0, 'screened_closed_before_ai': 0,
              'unreadable_before_ai': 0, 'pursue': 0, 'review': 0, 'watch': 0, 'investigate': 0,
              'verified_actionable': 0, 'unverified_relevant': 0,
              'budget': {'web_tool_calls': 0, 'document_ai_calls': 0, 'token_usage': {}},
              'research_trace': [], 'diagnostics': {'errors': [], 'warnings': [], 'resolution': [], 'stage_counts': {}, 'selected': []}, 'run_status': 'running'}
    selected = []
    with tempfile.TemporaryDirectory(prefix='opportunity_', dir='/tmp') as dirname:
        base = Path(dirname)
        mongo = MongoClient(mongo_uri, serverSelectionTimeoutMS=8000)
        try:
            mongo.admin.command('ping')
            db = mongo['vinyl_collection']
            emailed = db['opportunity_digest_emailed']
            runs = db['opportunity_agent_runs']
            processed = db['opportunity_digest_processed']
            all_discoveries = []
            for company in companies:
                try:
                    discovery_file = base / f'{company}_discovered.json'
                    if discovery_enabled:
                        discovery_args = SimpleNamespace(company=company, as_of=day,
                            limit=per_company, max_search_calls=max_search_calls,
                            search_model=search_model, ai_timeout=125, output=str(discovery_file))
                        pilot.discover(discovery_args)
                        discovery = json.loads(discovery_file.read_text())
                        result['budget']['web_tool_calls'] += discovery.get('search_tool_calls', 0)
                    else:
                        leads = [l for l in event.get('input_leads', []) if l.get('company') == company]
                        discovery = {'leads': leads}
                        discovery_file.write_text(json.dumps(discovery))
                    result['found'] += len(discovery['leads'])
                    # Every discovered opportunity must have a terminal outcome.
                    trace_by_id = {}
                    for n, lead in enumerate(discovery['leads']):
                        trace_id = f'{company}:{n}'
                        item = {'trace_id': trace_id, 'company': company, 'id': lead.get('id'),
                                'title': lead.get('title'), 'buyer': lead.get('buyer'),
                                'listing_url': lead.get('url'), 'stage': 'discovered',
                                'outcome': 'pending', 'reason': None, 'issuer_url': None,
                                'verification_attempts': [], 'reviewed': False}
                        result['research_trace'].append(item)
                        all_discoveries.append({**lead, '_trace_id': trace_id})
                        trace_by_id[lead.get('id') or f'index:{n}'] = item
                    if not discovery['leads']:
                        continue
                    resolved_file = base / f'{company}_resolved.json'
                    resolve_args = SimpleNamespace(input=str(discovery_file), output=str(resolved_file),
                        as_of=day, limit=per_company, official_sources=str(_RESOURCE_DIR / 'official_sources.json'),
                        timeout=timeout, web=True, search_model=search_model,
                        max_search_calls=2, ai_timeout=125)
                    pilot.resolve_issuers(resolve_args)
                    resolution_report = json.loads(resolved_file.read_text())
                    resolved = resolution_report['leads']
                    if len(resolved) < len(discovery['leads']):
                        result['diagnostics']['warnings'].append(
                            f'{company}: issuer resolver returned {len(resolved)} of {len(discovery["leads"])} discovered leads')
                    result['budget']['issuer_lookup_requests'] = result['budget'].get('issuer_lookup_requests', 0) + (1 if resolution_report.get('api_usage') else 0)
                    result['budget']['issuer_lookup_usage'] = result['budget'].get('issuer_lookup_usage', {})
                    if resolution_report.get('api_usage'):
                        result['budget']['issuer_lookup_usage'][company] = resolution_report['api_usage']
                    for i, lead in enumerate(resolved):
                        attempts = lead.get('resolution_attempts', [])
                        item = trace_by_id.get(lead.get('id'))
                        if item is None:
                            # ID-less and rewritten leads still receive trace entries.
                            item = next((t for t in result['research_trace'] if t['company'] == company
                                         and t['outcome'] == 'pending'
                                         and t['listing_url'] in (lead.get('original_url'), lead.get('url'))), None)
                        if item is None:
                            item = {'trace_id': f'{company}:extra:{i}', 'company': company,
                                    'id': lead.get('id'), 'title': lead.get('title'),
                                    'buyer': lead.get('buyer'), 'listing_url': lead.get('original_url') or lead.get('url'),
                                    'stage': 'resolved', 'outcome': 'pending', 'reason': None,
                                    'issuer_url': None, 'verification_attempts': [], 'reviewed': False}
                            result['research_trace'].append(item)
                        item['stage'] = 'issuer_resolution'
                        item['issuer_url'] = lead.get('url') if lead.get('resolution_status') == 'issuer_page_retrieved_and_matched' else None
                        item['verification_attempts'] = attempts[:12]
                        item['resolution_status'] = lead.get('resolution_status')
                        item['previously_seen'] = bool(lead.get('previously_seen'))
                        if lead.get('resolution_status') != 'issuer_page_retrieved_and_matched':
                            item.update(outcome='not_reviewed', reason='issuer_not_verified')
                        elif lead.get('previously_seen') and event.get('include_known') is not True:
                            item.update(outcome='not_reviewed', reason='benchmark_known_skipped')
                        result['diagnostics']['resolution'].append({
                            'company': company, 'title': lead.get('title'),
                            'listing_url': lead.get('original_url') or lead.get('url'),
                            'status': lead.get('resolution_status'),
                            'previously_seen': bool(lead.get('previously_seen')),
                            'reason': attempts[-1].get('error') if attempts and isinstance(attempts[-1], dict) else None,
                            'attempts': len(attempts),
                            'issuer_candidates': lead.get('issuer_candidates', [])[:5]})
                    # Scope and issuer verification gate before expensive review.
                    eligible = [l for l in resolved if l.get('resolution_status') == 'issuer_page_retrieved_and_matched'
                                and not l.get('previously_seen')]
                    # Optionally allow benchmark opportunities for explicit local deployment tests.
                    if event.get('include_known') is True:
                        eligible = [l for l in resolved if l.get('resolution_status') == 'issuer_page_retrieved_and_matched']
                    capped = eligible[max_review_leads:]
                    eligible = eligible[:max_review_leads]
                    for lead in capped:
                        item = trace_by_id.get(lead.get('id'))
                        if item:
                            item.update(outcome='not_reviewed', reason='max_review_leads_limit')
                    for lead in eligible:
                        item = trace_by_id.get(lead.get('id'))
                        if item:
                            item.update(stage='document_review', outcome='pending', reason=None)
                    if not eligible:
                        result['diagnostics']['warnings'].append(f'{company}: 0/{len(resolved)} leads passed official-source gate; see diagnostics.resolution')
                        result['unverified_relevant'] += len(resolved)
                        continue
                    review_input = base / f'{company}_review_input.json'
                    review_input.write_text(json.dumps({'leads': eligible}))
                    review_output = base / f'{company}_review.json'
                    remaining = max_ai_calls - result['budget']['document_ai_calls']
                    review_args = SimpleNamespace(input=str(review_input), output=str(review_output),
                        id=None, ai=ai and remaining > 0, as_of=day, model=review_model,
                        timeout=timeout, ai_timeout=125, max_documents=max_docs,
                        max_leads=max(1, len(eligible)), max_evidence_chars=11000,
                        max_completion_tokens=3500, max_ai_calls=max(0, remaining),
                        debug_dir=str(base / f'{company}_debug'))
                    rfp_review.run(review_args)
                    report = json.loads(review_output.read_text())
                    result['reviewed'] += len(report['results'])
                    result['details_checked'] += sum(len(x.get('attachments', [])) + 1 for x in report['results'])
                    result['budget']['document_ai_calls'] += report.get('model_calls', 0)
                    result['budget']['token_usage'].update(report.get('api_usage', {}))
                    result['classification_errors'] += len(report.get('errors', []))
                    for entry in report['results']:
                        item = trace_by_id.get(entry.get('id'))
                        if item:
                            item.update(stage='document_review', reviewed=True,
                                        outcome='reviewed_not_selected', reason='no_accepted_ai_findings')
                        a = entry.get('assessment', {})
                        accepted = a.get('findings', {})
                        bytype = {}
                        for kind in ('deadline', 'insurance', 'qualifications', 'submission', 'scope', 'commercial'):
                            bytype[kind] = [x for x in accepted.get(kind, [])
                                            if x.get('extraction_method') == 'ai' and x.get('evidence_valid')]
                        if not any(bytype.values()):
                            result['unverified_relevant'] += 1
                            continue
                        # Do not claim eligible/open when full RFP is truncated or amendments may be missing.
                        match = {'id': entry['id'], 'company': company, 'title': entry['title'],
                            'organization': entry['buyer'], 'url': entry['source_url'], 'score': 0,
                            'tier': 'investigate', 'stage': 'rfp', 'deadline': 'verify in current addenda',
                            'budget': 'not established', 'role': 'potential prime',
                            'source_quality': 'issuer page matched, document review incomplete',
                            'buyer_need': entry['title'], 'deliverable': entry['title'],
                            'next_action': 'Confirm missing/truncated sections, eligibility and insurance',
                            'fit_evidence': [], 'unknowns': ['Document text may be truncated',
                                'Insurance eligibility and bid submission need final manual review'],
                            'disqualifiers': [], 'requirements_by_type': bytype,
                            'content_hash': __import__('hashlib').sha256(json.dumps(bytype, sort_keys=True).encode()).hexdigest()}
                        key = match['id'] + '|' + company
                        # Persist reviewed metadata under the established original collection key.
                        if not dry_run:
                            processed.update_one({'_id': match['id']}, {'$set': {
                            'content_hash': match['content_hash'], 'analyzer': VERSION,
                            'classification': {'tier': 'investigate', 'coverage': a.get('coverage', {})},
                            'processed_at': now.isoformat()}}, upsert=True)
                        if item:
                            item.update(outcome='selected_for_notification', reason=None)
                        previous = emailed.find_one({'_id': key})
                        if previous and previous.get('content_hash') == match['content_hash']:
                            result['already_notified'] += 1
                            if item:
                                item.update(outcome='already_notified', reason='unchanged_content_hash')
                            continue
                        selected.append(match)
                    if debug_bucket:
                        s3 = boto3.client('s3')
                        prefix = f'opportunity-agent/{day}/{now.strftime("%H%M%S")}/{company}'
                        # Diagnostic files contain source extracts and model responses: private bucket only.
                        for file in [review_output, *sorted((base / f'{company}_debug').glob('*.validation.json'))]:
                            s3.upload_file(str(file), debug_bucket, f'{prefix}/{file.name}',
                                           ExtraArgs={'ServerSideEncryption': 'AES256'})
                except Exception as exc:
                    for item in result['research_trace']:
                        if item['company'] == company and item['outcome'] == 'pending':
                            item.update(outcome='failed', reason=f'{type(exc).__name__}: {str(exc)[:160]}')
                    result['classification_errors'] += 1
                    result['diagnostics']['errors'].append({'company': company, 'type': type(exc).__name__,
                                                            'detail': str(exc)[:350]})
                    LOG.exception('Company pipeline failure: %s', company)
            # Separate verified review from unverified but plausibly relevant discovery.
            # Do not silently suppress uncertain prospects. Expired known dates and
            # duplicates are excluded; missing dates remain explicitly unknown.
            seen_projects = set(_project_key(x) for x in selected)
            unverified_digest = []
            for trace in result['research_trace']:
                if trace.get('outcome') != 'not_reviewed' or trace.get('reason') != 'issuer_not_verified':
                    continue
                source_lead = next((x for x in all_discoveries if x.get('_trace_id') == trace['trace_id']), None)
                if not source_lead: continue
                expired, known_date, date_field = _expiration_check(source_lead, day)
                if expired:
                    trace.update(outcome='excluded',reason='expired_explicit_deadline',deadline=known_date)
                    result['screened_closed_before_ai'] += 1
                    continue
                pkey = _project_key(source_lead)
                if pkey in seen_projects:
                    trace.update(outcome='excluded',reason='duplicate_project_in_digest')
                    continue
                seen_projects.add(pkey)
                listing = source_lead.get('url') or trace.get('listing_url')
                token = hashlib.sha256((trace['company']+'|'+pkey).encode()).hexdigest()[:20]
                item = {'id': 'unverified:' + token, 'company': trace['company'],
                        'title': trace['title'] or source_lead.get('title') or 'Untitled opportunity',
                        'organization': trace['buyer'] or source_lead.get('buyer') or 'Buyer unconfirmed',
                        'url': listing, 'tier': 'unverified', 'deadline':known_date or 'Unconfirmed',
                        'source_quality':'third-party discovery, issuer not confirmed',
                        'verification_reason': ((trace.get('verification_attempts') or [{}])[-1].get('error') or 'No confirmed issuer notice'),
                        'next_action':'Check the buyer identity, official solicitation and closing date before bidding',
                        'content_hash': hashlib.sha256(json.dumps([trace['company'],pkey,listing,known_date],sort_keys=True).encode()).hexdigest()}
                previous = emailed.find_one({'_id': item['id'] + '|' + item['company']})
                if previous and previous.get('content_hash') == item['content_hash']:
                    trace.update(outcome='already_notified',reason='unchanged_unverified_lead')
                    result['already_notified'] += 1
                    continue
                unverified_digest.append(item)
                trace.update(outcome='selected_unverified',reason='issuer_unverified_email_with_warning')
            selected.extend(unverified_digest)
            result['unverified_in_digest'] = len(unverified_digest)
            counts = {}
            for item in result['research_trace']:
                key = item['reason'] or item['outcome']
                counts[key] = counts.get(key, 0) + 1
            result['diagnostics']['stage_counts'] = counts
            LOG.warning('Opportunity pipeline: found=%s reviewed=%s dispositions=%s', result['found'], result['reviewed'], json.dumps(counts, sort_keys=True))
            for item in result['research_trace']:
                LOG.info('Opportunity disposition: %s', json.dumps({k: item.get(k) for k in ('trace_id','company','id','title','listing_url','issuer_url','resolution_status','outcome','reason','verification_attempts')}, default=str)[:2400])
            # Hard invariant: never silently lose a discovery between stages.
            for item in result['research_trace']:
                if item['outcome'] == 'pending':
                    item.update(outcome='failed', reason='unaccounted_pipeline_transition')
            result['run_status'] = ('completed_with_errors' if result['diagnostics']['errors']
                                    else 'completed_unverified_only' if result['unverified_in_digest'] > 0 and result['reviewed'] == 0
                                    else 'incomplete_no_reviews' if result['found'] > 0 and result['reviewed'] == 0
                                    else 'completed')
            if result['run_status'] not in ('completed','completed_unverified_only'):
                result['diagnostics']['warnings'].append('Run not fully successful: inspect research_trace and stage_counts')
            if result['run_status'] == 'completed_unverified_only':
                result['diagnostics']['warnings'].append('Only unverified third-party leads were sent; no documents passed official review')
            result['investigate'] = sum(x['tier'] == 'investigate' for x in selected)
            result['unverified_relevant'] += sum(x['tier'] == 'investigate' for x in selected)
            result['diagnostics']['selected'] = [{'company': x['company'], 'title': x['title'],
                                                 'url': x['url'], 'tier': x['tier']} for x in selected]
            report_body = _email_text(selected, day)
            report_html = _email_html(selected, day)
            if dry_run:
                result['preview'] = report_body[:18000]
                result['preview_html'] = report_html[:30000]
            elif selected:
                boto3.client('ses').send_email(Source=sender,
                    Destination={'ToAddresses': [x.strip() for x in to.split(',') if x.strip()]},
                    Message={'Subject': {'Data': f'Procurement digest: {sum(x["tier"] == "investigate" for x in selected)} reviewed, {sum(x["tier"] == "unverified" for x in selected)} unverified | {day}'},
                             'Body': {'Text': {'Data': report_body, 'Charset':'UTF-8'}, 'Html': {'Data': report_html,'Charset':'UTF-8'}}})
                for x in selected:
                    emailed.update_one({'_id': x['id'] + '|' + x['company']}, {'$set': {
                        'sent_at': now.isoformat(), 'content_hash': x['content_hash'],
                        'title': x['title'], 'score': 0, 'tier': x['tier'],
                        'open_status': 'unknown'}}, upsert=True)
                result['emailed'] = len(selected)
            if not dry_run:
                runs.insert_one({'date': now.isoformat(), 'version': VERSION, 'totals': {
                c: sum(x['company'] == c for x in selected) for c in COMPANIES},
                'budget_calls': {'web': result['budget']['web_tool_calls'],
                                 'analysis': result['budget']['document_ai_calls']},
                'diagnostics': result['diagnostics']})
            return result
        finally:
            mongo.close()
